import { readFile, writeFile, mkdir, rename } from 'node:fs/promises';
import { dirname } from 'node:path';
import { randomUUID } from 'node:crypto';

export class BookStore {
  constructor(filePath) {
    this.filePath = filePath;
    this.books = null;
    // Writes are chained so two quick requests can't interleave partial files.
    this.pending = Promise.resolve();
  }

  async load() {
    if (this.books) return this.books;
    try {
      const raw = await readFile(this.filePath, 'utf8');
      const parsed = JSON.parse(raw);
      this.books = Array.isArray(parsed) ? parsed : [];
    } catch (err) {
      if (err.code !== 'ENOENT') throw err;
      this.books = [];
    }
    return this.books;
  }

  async save() {
    this.pending = this.pending.then(async () => {
      await mkdir(dirname(this.filePath), { recursive: true });
      // Write to a temp file then rename so a crash mid-write can't corrupt the data.
      const tmp = `${this.filePath}.tmp`;
      await writeFile(tmp, JSON.stringify(this.books, null, 2) + '\n');
      await rename(tmp, this.filePath);
    });
    return this.pending;
  }

  async all() {
    return [...(await this.load())];
  }

  async reading() {
    return (await this.load()).filter((b) => !b.finishedAt);
  }

  async finished() {
    return (await this.load())
      .filter((b) => b.finishedAt)
      .sort((a, b) => b.finishedAt.localeCompare(a.finishedAt));
  }

  async get(id) {
    return (await this.load()).find((b) => b.id === id) ?? null;
  }

  async add({ title, author, notes = '' }) {
    title = String(title ?? '').trim();
    author = String(author ?? '').trim();
    notes = String(notes ?? '').trim();
    if (!title) throw new ValidationError('Title is required.');
    if (!author) throw new ValidationError('Author is required.');

    const book = {
      id: randomUUID(),
      title,
      author,
      notes,
      startedAt: new Date().toISOString(),
      finishedAt: null,
    };
    (await this.load()).push(book);
    await this.save();
    return book;
  }

  async finish(id) {
    const book = await this.get(id);
    if (!book) return null;
    if (!book.finishedAt) {
      book.finishedAt = new Date().toISOString();
      await this.save();
    }
    return book;
  }

  async updateNotes(id, notes) {
    const book = await this.get(id);
    if (!book) return null;
    book.notes = String(notes ?? '').trim();
    await this.save();
    return book;
  }
}

export class ValidationError extends Error {}

