import { ValidationError } from './store.mjs';
import { homePage, bookPage, notFoundPage } from './views.mjs';

const MAX_BODY = 64 * 1024;

function readBody(req) {
  return new Promise((resolve, reject) => {
    let size = 0;
    const chunks = [];
    req.on('data', (chunk) => {
      size += chunk.length;
      if (size > MAX_BODY) {
        reject(new Error('Request body too large'));
        req.destroy();
        return;
      }
      chunks.push(chunk);
    });
    req.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')));
    req.on('error', reject);
  });
}

async function readForm(req) {
  const params = new URLSearchParams(await readBody(req));
  return Object.fromEntries(params);
}

function html(res, status, body) {
  res.writeHead(status, { 'content-type': 'text/html; charset=utf-8' });
  res.end(body);
}

function redirect(res, location) {
  res.writeHead(303, { location });
  res.end();
}

function baseUrl(req) {
  const proto = req.headers['x-forwarded-proto'] ?? 'http';
  const host = req.headers['x-forwarded-host'] ?? req.headers.host ?? 'localhost';
  return `${proto}://${host}`;
}

export function createHandler(store) {
  return async function handle(req, res) {
    const url = new URL(req.url, 'http://localhost');
    const path = url.pathname.replace(/\/+$/, '') || '/';
    const { method } = req;

    try {
      if (path === '/' && method === 'GET') {
        return html(res, 200, homePage({ reading: await store.reading(), finished: await store.finished() }));
      }

      if (path === '/books' && method === 'POST') {
        const form = await readForm(req);
        try {
          const book = await store.add(form);
          return redirect(res, `/books/${book.id}`);
        } catch (err) {
          if (!(err instanceof ValidationError)) throw err;
          return html(
            res,
            400,
            homePage({ reading: await store.reading(), finished: await store.finished(), error: err.message, values: form }),
          );
        }
      }

      const bookMatch = path.match(/^\/books\/([^/]+)(?:\/(finish|notes))?$/);
      if (bookMatch) {
        const [, id, action] = bookMatch;
        if (!action && method === 'GET') {
          const book = await store.get(id);
          if (!book) return html(res, 404, notFoundPage());
          return html(res, 200, bookPage(book, `${baseUrl(req)}/books/${book.id}`));
        }
        if (action === 'finish' && method === 'POST') {
          const book = await store.finish(id);
          if (!book) return html(res, 404, notFoundPage());
          return redirect(res, url.searchParams.get('back') === 'home' ? '/' : `/books/${id}`);
        }
        if (action === 'notes' && method === 'POST') {
          const form = await readForm(req);
          const book = await store.updateNotes(id, form.notes);
          if (!book) return html(res, 404, notFoundPage());
          return redirect(res, `/books/${id}`);
        }
      }

      return html(res, 404, notFoundPage());
    } catch (err) {
      console.error(err);
      if (!res.headersSent) html(res, 500, '<h1>Something went wrong</h1>');
      else res.end();
    }
  };
}

