  ul.books li form { margin-left: auto; }
  .empty { opacity: .6; font-style: italic; }
  form.add { display: grid; gap: .6rem; margin-top: 1rem; }
  label { display: grid; gap: .2rem; font-size: .9rem; }
  input, textarea { font: inherit; padding: .4rem .5rem; border: 1px solid #8886; border-radius: 4px; background: transparent; color: inherit; }
  textarea { min-height: 5rem; resize: vertical; }
  button { font: inherit; padding: .35rem .8rem; border: 1px solid #8888; border-radius: 4px; background: #8882; cursor: pointer; }
  button.primary { justify-self: start; }
