  nav { margin-bottom: 1rem; font-size: .9rem; }
  .share { margin-top: 2rem; font-size: .9rem; }
  .share input { width: 100%; }
`;

function layout(title, body) {
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${escapeHtml(title)}</title>
<style>${styles}</style>
</head>
<body>
${body}
</body>
</html>
`;
}

function formatDate(iso) {
  if (!iso) return '';
  return new Date(iso).toLocaleDateString('en-US', { year: 'numeric', month: 'short', day: 'numeric' });
}

function bookItem(book) {
  const finishButton = book.finishedAt
    ? `<span class="meta">finished ${escapeHtml(formatDate(book.finishedAt))}</span>`
    : `<form method="post" action="/books/${escapeHtml(book.id)}/finish"><button>Mark finished</button></form>`;
