import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import { mkdtemp, rm, readFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { BookStore, ValidationError } from '../src/store.mjs';

let dir;
let file;

beforeEach(async () => {
  dir = await mkdtemp(join(tmpdir(), 'books-'));
  file = join(dir, 'books.json');
});

afterEach(() => rm(dir, { recursive: true, force: true }));

describe('BookStore', () => {
  it('starts empty when the file does not exist', async () => {
    const store = new BookStore(file);
    expect(await store.all()).toEqual([]);
  });

  it('adds a book and persists it to disk', async () => {
    const store = new BookStore(file);
    const book = await store.add({ title: ' Dune ', author: 'Frank Herbert', notes: 'spice' });

    expect(book.title).toBe('Dune');
    expect(book.finishedAt).toBeNull();

    const onDisk = JSON.parse(await readFile(file, 'utf8'));
    expect(onDisk).toHaveLength(1);
    expect(onDisk[0].id).toBe(book.id);
  });

  it('reloads books from disk after a restart', async () => {
    const first = new BookStore(file);
    const book = await first.add({ title: 'Dune', author: 'Frank Herbert' });

    const second = new BookStore(file);
    expect(await second.get(book.id)).toMatchObject({ title: 'Dune', author: 'Frank Herbert', notes: '' });
  });

  it('rejects books without a title or author', async () => {
    const store = new BookStore(file);
    await expect(store.add({ title: '', author: 'x' })).rejects.toBeInstanceOf(ValidationError);
    await expect(store.add({ title: 'x', author: '   ' })).rejects.toBeInstanceOf(ValidationError);
    expect(await store.all()).toEqual([]);
  });

  it('moves a book from reading to finished', async () => {
    const store = new BookStore(file);
    const a = await store.add({ title: 'A', author: 'x' });
    const b = await store.add({ title: 'B', author: 'y' });

    await store.finish(a.id);

    expect((await store.reading()).map((x) => x.id)).toEqual([b.id]);
    expect((await store.finished()).map((x) => x.id)).toEqual([a.id]);
    expect((await store.get(a.id)).finishedAt).toMatch(/^\d{4}-/);
  });

  it('returns null when finishing an unknown book', async () => {
    const store = new BookStore(file);
    expect(await store.finish('nope')).toBeNull();
  });

  it('updates notes', async () => {
    const store = new BookStore(file);
    const book = await store.add({ title: 'A', author: 'x' });
    await store.updateNotes(book.id, 'great so far');
    expect((await store.get(book.id)).notes).toBe('great so far');
  });
});

