import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import { createServer } from 'node:http';
import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { BookStore } from '../src/store.mjs';
import { createHandler } from '../src/app.mjs';

let dir;
let server;
let base;
let store;

beforeEach(async () => {
  dir = await mkdtemp(join(tmpdir(), 'books-'));
  store = new BookStore(join(dir, 'books.json'));
  server = createServer(createHandler(store));
  await new Promise((resolve) => server.listen(0, '127.0.0.1', resolve));
  base = `http://127.0.0.1:${server.address().port}`;
});

afterEach(async () => {
  await new Promise((resolve) => server.close(resolve));
  await rm(dir, { recursive: true, force: true });
});

const post = (path, data) =>
  fetch(base + path, {
    method: 'POST',
    redirect: 'manual',
    headers: { 'content-type': 'application/x-www-form-urlencoded' },
    body: new URLSearchParams(data),
  });

describe('book tracker HTTP app', () => {
  it('shows empty states on the home page', async () => {
    const res = await fetch(base + '/');
    const body = await res.text();
    expect(res.status).toBe(200);
    expect(body).toContain('Currently reading');
    expect(body).toContain("You're not reading anything right now.");
    expect(body).toContain('Nothing finished yet.');
  });

  it('adds a book via the form and redirects to its page', async () => {
    const res = await post('/books', { title: 'Dune', author: 'Frank Herbert', notes: 'sand' });
    expect(res.status).toBe(303);
    const location = res.headers.get('location');
    expect(location).toMatch(/^\/books\/[\w-]+$/);

    const page = await (await fetch(base + location)).text();
    expect(page).toContain('<h1>Dune</h1>');
    expect(page).toContain('by Frank Herbert');
    expect(page).toContain('sand');
    expect(page).toContain(`${base}${location}`); // shareable link

    const home = await (await fetch(base + '/')).text();
    expect(home).toContain('Dune');
    expect(home).not.toContain("You're not reading anything right now.");
  });

  it('re-renders the form with an error when the title is missing', async () => {
    const res = await post('/books', { title: '', author: 'Someone' });
    expect(res.status).toBe(400);
    const body = await res.text();
    expect(body).toContain('Title is required.');
    expect(body).toContain('value="Someone"');
  });

  it('marks a book as finished', async () => {
    const book = await store.add({ title: 'Dune', author: 'Frank Herbert' });

    const res = await post(`/books/${book.id}/finish?back=home`, {});
    expect(res.status).toBe(303);
    expect(res.headers.get('location')).toBe('/');

    const home = await (await fetch(base + '/')).text();
    const finishedSection = home.slice(home.indexOf('<h2>Finished</h2>'));
    expect(finishedSection).toContain('Dune');
    expect(home).toContain("You're not reading anything right now.");
  });

  it('saves notes from the book page', async () => {
    const book = await store.add({ title: 'Dune', author: 'Frank Herbert' });
    const res = await post(`/books/${book.id}/notes`, { notes: 'Loved the ending' });
    expect(res.status).toBe(303);
    expect((await store.get(book.id)).notes).toBe('Loved the ending');
  });

  it('escapes HTML in user input', async () => {
    await store.add({ title: '<script>alert(1)</script>', author: 'x' });
    const home = await (await fetch(base + '/')).text();
    expect(home).not.toContain('<script>alert(1)</script>');
    expect(home).toContain('&lt;script&gt;');
  });

  it('returns 404 for unknown books and routes', async () => {
    expect((await fetch(base + '/books/does-not-exist')).status).toBe(404);
    expect((await fetch(base + '/nope')).status).toBe(404);
    expect((await post('/books/does-not-exist/finish', {})).status).toBe(404);
  });
});

