  button.primary { justify-self: start; }
  .meta { opacity: .7; font-size: .9rem; }
  .notes { white-space: pre-wrap; background: #8881; padding: 1rem; border-radius: 6px; }
  .error { color: #c33; }
  .badge { font-size: .75rem; padding: .1rem .45rem; border-radius: 999px; background: #3a83; }
  nav { margin-bottom: 1rem; font-size: .9rem; }
  .share { margin-top: 2rem; font-size: .9rem; }
  .share input { width: 100%; }
`;

function layout(title, body) {
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${escapeHtml(title)}</title>
<style>${styles}</style>
</head>
<body>
${body}
</body>
</html>
`;
}

function formatDate(iso) {
  if (!iso) return '';
  return new Date(iso).toLocaleDateString('en-US', { year: 'numeric', month: 'short', day: 'numeric' });
}

function bookItem(book) {
  const finishButton = book.finishedAt
    ? `<span class="meta">finished ${escapeHtml(formatDate(book.finishedAt))}</span>`
    : `<form method="post" action="/books/${escapeHtml(book.id)}/finish?back=home"><button>Mark finished</button></form>`;
  return `<li>
    <a class="title" href="/books/${escapeHtml(book.id)}">${escapeHtml(book.title)}</a>
    <span class="author">${escapeHtml(book.author)}</span>
    ${finishButton}
  </li>`;
}

function bookList(books, emptyMessage) {
  if (books.length === 0) return `<p class="empty">${escapeHtml(emptyMessage)}</p>`;
  return `<ul class="books">${books.map(bookItem).join('\n')}</ul>`;
}

export function homePage({ reading, finished, error = null, values = {} }) {
  return layout(
    'My Books',
    `<h1>My Books</h1>

<h2>Currently reading</h2>
${bookList(reading, "You're not reading anything right now.")}

<h2>Finished</h2>
${bookList(finished, 'Nothing finished yet.')}

<h2>Add a book</h2>
${error ? `<p class="error">${escapeHtml(error)}</p>` : ''}
<form class="add" method="post" action="/books">
  <label>Title <input name="title" required value="${escapeHtml(values.title)}"></label>
  <label>Author <input name="author" required value="${escapeHtml(values.author)}"></label>
  <label>Notes <textarea name="notes">${escapeHtml(values.notes)}</textarea></label>
  <button class="primary" type="submit">Add book</button>
</form>`,
  );
}

export function bookPage(book, shareUrl) {
  const status = book.finishedAt
    ? `<span class="badge">Finished ${escapeHtml(formatDate(book.finishedAt))}</span>`
    : `<form method="post" action="/books/${escapeHtml(book.id)}/finish" style="display:inline"><button>Mark finished</button></form>`;
  return layout(
    `${book.title} – My Books`,
    `<nav><a href="/">← All books</a></nav>
<h1>${escapeHtml(book.title)}</h1>
<p class="meta">by ${escapeHtml(book.author)} · started ${escapeHtml(formatDate(book.startedAt))} ${status}</p>

<h2>Notes</h2>
<form method="post" action="/books/${escapeHtml(book.id)}/notes" class="add">
  <textarea name="notes">${escapeHtml(book.notes)}</textarea>
  <button class="primary" type="submit">Save notes</button>
</form>

<div class="share">
  <label>Share this book <input readonly value="${escapeHtml(shareUrl)}" onclick="this.select()"></label>
</div>`,
  );
}

export function notFoundPage() {
  return layout('Not found', `<nav><a href="/">← All books</a></nav><h1>Book not found</h1><p>That book doesn't exist (maybe it was never added, or the link is wrong).</p>`);
}
